export const northvaleLocations:Location[]=[
  location({"index":1,"name":"Old Vale","slug":"old-vale","description":"NorthVale's historic year-round center, where mining-era brick, timber storefronts, apartments, civic buildings, and ordinary local routines sit below the resort lights.","category":"district","type":"district","activities":["coffee","books","local dining","cinema","community events"],"hours":null,"backstory":"Old Vale survived the end of silver because it became useful rather than grand. Most buildings have been repaired many times, and residents care more about who keeps a business open in April than who renovates it for tourists in December.","socialTexture":"Locals, town staff, long-term transplants, and off-shift resort workers overlap here without needing a special occasion.","visualAnchors":["brick storefronts","snowbanks","warm apartment windows","municipal lamps","mountain visible at street end"]}),
  location({"index":2,"name":"Summit Village","slug":"summit-village","description":"The resort base district: polished lodges, rentals, restaurants, spa rooms, public fire pits, and the visible front door of NorthVale Mountain.","category":"district","type":"district","activities":["lodging","apres","rentals","dining","gondola access"],"hours":null,"backstory":"Summit Village was built in layers around the original rope-tow field. Its public spaces are designed for visitors, but its service corridors, staff entrances, early shifts, and after-close rituals reveal the working town beneath the brochure.","socialTexture":"Guests dominate midday; employees and regulars reclaim the village before first chair and after the last shuttle.","visualAnchors":["stone-and-cedar lodges","gondola plaza","fire pits","ski racks","amber windows against blue snow"]}),
  location({"index":3,"name":"Timberline Commons","slug":"timberline-commons","description":"A dense, younger district of seasonal housing, cheap food, nightlife, equipment work, laundry, climbing, and improvised community.","category":"district","type":"district","activities":["employee housing","live music","late food","climbing","gear work"],"hours":null,"backstory":"Timberline grew from railway service buildings and low-cost apartments that the resort never managed to absorb. It is noisy, overbooked, socially porous, and often the first place newcomers feel known.","socialTexture":"Friend groups form quickly because shifts, rent, rides, laundry, and bad weather force people into one another's lives.","visualAnchors":["converted warehouses","shuttle stop","snowy balconies","murals","late-night windows"]}),
  location({"index":4,"name":"NorthVale Mountain","slug":"northvale-mountain","description":"The operational and recreational spine of the world: lifts, ski school, patrol, forecasting, terrain, controlled gates, warming lodges, and exposed alpine weather.","category":"district","type":"district","activities":["skiing","snowboarding","lessons","patrol","mountain operations"],"hours":null,"backstory":"The mountain began as a community rope tow in 1947 and remains emotionally public even though a resort company operates it. Every opening decision involves weather, machinery, labor, safety, and the expectations of thousands of people below.","socialTexture":"Before opening, the mountain belongs to workers. Midday it becomes public spectacle. After sweep, it turns quiet, technical, and intimate again.","visualAnchors":["gondola lines","groomed runs","patrol sleds","snow guns","high alpine ridge"]}),
  location({"index":5,"name":"Pine Lake","slug":"pine-lake","description":"A quieter year-round district of Nordic trails, cabins, horses, sauna culture, lake recreation, and residents who prefer the valley's slower edge.","category":"district","type":"district","activities":["Nordic skiing","sauna","cabins","skating","summer paddling"],"hours":null,"backstory":"Pine Lake was once a mill pond and workers' settlement. It became a recreation district gradually, retaining modest cabins and a strong year-round population rather than becoming a private resort enclave.","socialTexture":"Morning athletes, families, guides, and quiet dates define the lake more than nightlife does.","visualAnchors":["frozen lake","pine forest","low cabins","Nordic tracks","steam in cold air"]}),
  location({"index":6,"name":"Silver Basin","slug":"silver-basin","description":"Remote high country beyond the main resort, shaped by old mine roads, hot springs, backcountry guiding, rescue work, snowcats, and serious weather.","category":"district","type":"district","activities":["backcountry travel","hot springs","guiding","mine history","rescue"],"hours":null,"backstory":"Silver Basin holds the remains of NorthVale's original mining economy and the watershed that supplies much of the valley. It is beautiful, useful, dangerous, and central to the current access debate.","socialTexture":"The basin rewards preparation and long conversations. People rarely arrive accidentally, and weather can make every plan provisional.","visualAnchors":["high basin","avalanche paths","weathered mine structures","hot-spring steam","snowcat tracks"]}),
  location({"index":7,"parent":1,"district":"Old Vale","name":"Lantern Square","slug":"lantern-square","description":"A brick-and-stone public square with a simple fountain, heated benches, market stalls, a shuttle stop, and a direct view of the lit mountain.","category":"plaza","type":"landmark","activities":["market browsing","meetups","public events","people watching"],"hours":null,"backstory":"The square replaced a muddy freight yard in 1923. The lantern motif comes from rescue lights placed here after White Sunday, not from resort branding.","socialTexture":"It is the town's neutral ground: workers change buses, teenagers linger, civic events begin, and visitors finally realize people live here.","visualAnchors":["brick paving","heated benches","simple metal lanterns","market canopies","mountain view"]}),
  location({"index":8,"parent":1,"district":"Old Vale","name":"The Switchback","slug":"switchback-tavern","description":"A long-running tavern and neighborhood restaurant with a worn wood bar, fireplace, sturdy food, and a crowd that mixes locals with off-shift mountain staff.","category":"tavern","type":"venue","activities":["drinks","dinner","local conversation","watch parties"],"hours":{"open":"11:00","close":"02:00"},"backstory":"The room began as a railway dining hall. Every renovation has preserved one scarred communal table used during storms, elections, breakups, fundraisers, and rescue debriefs.","socialTexture":"Lunch is practical, dinner is intergenerational, and late night belongs to people whose shifts ended elsewhere.","visualAnchors":["scarred communal table","stone fireplace","dark timber bar","wet gloves drying","old rescue photographs"]}),
  location({"index":9,"parent":1,"district":"Old Vale","name":"Vale & Pine Books","slug":"vale-and-pine-books","description":"An independent bookstore with tall shelves, a mezzanine, a small reading stove, local maps, used paperbacks, and an unusually good mountain-history section.","category":"bookstore","type":"venue","activities":["book browsing","reading","map research","author events"],"hours":{"open":"09:00","close":"21:00"},"backstory":"The shop survived online competition by becoming part archive, part living room, and part unofficial lost-and-found for people deciding whether to stay another season.","socialTexture":"Quiet during first chair, busiest in storms, and intimate near closing when regulars finally talk.","visualAnchors":["tall wood shelves","mezzanine","cast-iron stove","map drawers","snowy street windows"]}),
  location({"index":10,"parent":1,"district":"Old Vale","name":"North Fork Coffee","slug":"north-fork-coffee","description":"A serious but unpretentious roastery and cafe inside a restored machine shop, known for early hours, shared tables, and staff who recognize mountain workers by schedule.","category":"cafe","type":"venue","activities":["coffee","breakfast","remote work","post-shift conversation"],"hours":{"open":"06:00","close":"18:00"},"backstory":"The original machine-shop floor remains visible beneath the cafe. A community ownership note issued during a bad snow year helped keep the business local.","socialTexture":"Pre-dawn is patrol and lift crews; late morning is visitors; afternoon is students, freelancers, and people avoiding a decision.","visualAnchors":["roaster","shared tables","industrial windows","ski boots near door","morning steam"]}),
  location({"index":11,"parent":1,"district":"Old Vale","name":"Rialto Mountain Cinema","slug":"rialto-mountain-cinema","description":"A restored single-screen cinema showing new releases, repertory films, local documentaries, and festival programs beneath a modest historic marquee.","category":"cinema","type":"venue","activities":["movies","documentary screenings","film nights","community talks"],"hours":{"open":"14:00","close":"23:30"},"backstory":"Opened in 1931, the Rialto stored decades of town footage in a projection-room closet nobody catalogued properly until recently.","socialTexture":"Matinees draw weather refugees; late screenings feel like private gatherings even when the room is full.","visualAnchors":["single auditorium","red seats","projection booth","restrained marquee","snowy alley exit"]}),
  location({"index":12,"parent":1,"district":"Old Vale","name":"NorthVale Community Clinic","slug":"northvale-community-clinic","description":"A compact modern clinic serving residents, visitors, athletes, seasonal workers, and mountain injuries without pretending every problem is glamorous.","category":"clinic","type":"venue","activities":["medical appointments","injury follow-up","community health","quiet waiting"],"hours":{"open":"08:00","close":"20:00"},"backstory":"The clinic expanded after the Vale Accord required the resort to support year-round emergency capacity. Funding remains a constant negotiation.","socialTexture":"Mornings are appointments; afternoons bring sprains and follow-ups; storm nights test every relationship between town and mountain.","visualAnchors":["practical reception","mudroom for boots","treatment rooms","mountain weather board","soft daylight"]}),
  location({"index":13,"parent":1,"district":"Old Vale","name":"Miners Hall","slug":"miners-hall","description":"A civic hall containing council chambers, a public archive, meeting rooms, a small museum, and the town's most consequential folding chairs.","category":"civic hall","type":"landmark","activities":["town meetings","archive research","exhibits","community events"],"hours":{"open":"09:00","close":"18:00"},"backstory":"Built by subscription in 1891, Miners Hall has hosted union meetings, rescue coordination, school dances, zoning fights, weddings, and every version of NorthVale arguing with itself.","socialTexture":"Quiet by day, emotionally crowded during public meetings, and unexpectedly warm during community suppers.","visualAnchors":["brick hall","wooden council chamber","archive cases","folding chairs","storm maps"]}),
  location({"index":14,"parent":2,"district":"Summit Village","name":"NorthVale Lodge","slug":"northvale-lodge","description":"A large but human-scale flagship hotel with a firelit lobby, practical ski storage, river-stone walls, and rooms overlooking either town or mountain operations.","category":"hotel","type":"venue","activities":["lodging","lobby meetings","dining","fireside conversation"],"hours":{"open":"00:00","close":"24:00"},"backstory":"The original 1956 lodge has been expanded repeatedly. Its oldest wing still reveals the community ski hill beneath the modern resort business.","socialTexture":"Guests fill the lobby, but staff and locals know the side tables, service elevator rhythms, and quiet hour after the last check-in.","visualAnchors":["river-stone fireplace","cedar beams","ski room","large lobby windows","lived-in hotel detail"]}),
  location({"index":15,"parent":2,"district":"Summit Village","name":"Gondola Commons","slug":"gondola-commons","description":"The main resort-base plaza beneath the Sunrise Gondola, with ticket windows, ski-school flags, racks, fire pits, shuttle arrivals, and constant movement.","category":"base plaza","type":"landmark","activities":["gondola boarding","meeting lessons","apres gathering","events"],"hours":{"open":"06:00","close":"22:00"},"backstory":"The Commons occupies the field where NorthVale's first rope tow began. A small brass marker is easy to miss beneath modern traffic.","socialTexture":"Tense and efficient before opening, crowded at midday, celebratory after sweep, and almost tender once the plaza empties.","visualAnchors":["gondola terminal","fire pits","ski racks","lesson flags","snowy pedestrian plaza"]}),
  location({"index":16,"parent":2,"district":"Summit Village","name":"Emberline Kitchen","slug":"emberline-kitchen","description":"A contemporary mountain restaurant built around an open hearth, seasonal ingredients, a visible kitchen, and food ambitious enough to matter without becoming theatrical.","category":"restaurant","type":"venue","activities":["dinner","chef counter","date nights","staff meal"],"hours":{"open":"17:00","close":"23:00"},"backstory":"Emberline replaced a failed luxury concept and kept the same expensive room while changing the menu, staffing, and relationship with local suppliers.","socialTexture":"Early service is polished; late service belongs to chefs, hotel staff, and diners who have stopped performing vacation.","visualAnchors":["open hearth","visible kitchen","stone walls","warm low light","snow beyond windows"]}),
  location({"index":17,"parent":2,"district":"Summit Village","name":"Aurora Spa","slug":"aurora-spa","description":"A modern spa and recovery center with treatment rooms, a warm pool, quiet lounges, and services used by workers and injured athletes as well as guests.","category":"spa","type":"venue","activities":["massage","recovery","warm pool","quiet conversation"],"hours":{"open":"08:00","close":"21:00"},"backstory":"Aurora gained local credibility only after introducing resident pricing and staff recovery hours required by the Vale Accord.","socialTexture":"Mornings are quiet, afternoons mix recovery and vacation, and closing time reveals the professionals caring for everyone else.","visualAnchors":["warm pool","stone treatment rooms","steam","soft amber lighting","mountain-facing glass"]}),
  location({"index":18,"parent":2,"district":"Summit Village","name":"The Alpine Room","slug":"alpine-room","description":"A sophisticated but relaxed apres lounge with a long fireplace, live acoustic sets, cocktails, small plates, and a crowd that changes completely after dinner.","category":"apres lounge","type":"venue","activities":["apres drinks","small plates","live music","late conversation"],"hours":{"open":"14:00","close":"01:00"},"backstory":"The Alpine Room was once the lodge cafeteria. Its polished renovation still leaves enough odd corners for staff, locals, and guests to occupy the same room differently.","socialTexture":"Loud after lifts close, composed during dinner, and socially revealing near midnight.","visualAnchors":["long fireplace","leather banquettes","acoustic stage","wet ski gear near entrance","amber reflections"]}),
  location({"index":19,"parent":2,"district":"Summit Village","name":"Basecamp Outfitters","slug":"basecamp-outfitters","description":"A high-volume rental and mountain shop with fitting benches, repair counters, lockers, and staff who can read a nervous beginner faster than a form can.","category":"rental shop","type":"venue","activities":["equipment rental","boot fitting","gear advice","repairs"],"hours":{"open":"07:00","close":"20:00"},"backstory":"Basecamp grew from the original cooperative equipment shed. Its busiest workers preserve a culture of practical advice beneath resort sales targets.","socialTexture":"Chaotic at opening, instructional all day, and candid after returns when the public floor finally quiets.","visualAnchors":["boot wall","fitting benches","rental racks","service counter","bright practical lighting"]}),
  location({"index":20,"parent":2,"district":"Summit Village","name":"Snowglass Gallery","slug":"snowglass-gallery","description":"A photography and contemporary art gallery focused on mountain labor, landscape, movement, and the lives usually cropped out of resort imagery.","category":"gallery","type":"venue","activities":["exhibitions","photography","opening nights","quiet dates"],"hours":{"open":"10:00","close":"21:00"},"backstory":"The gallery began as an empty real-estate showroom. Its first exhibition of lift mechanics and housekeepers drew more local attention than any landscape show.","socialTexture":"Calm by day, socially charged at openings, and intimate in the final hour before close.","visualAnchors":["white walls","large documentary photographs","cedar floor","snow-lit front glass","small opening-night bar"]}),
  location({"index":21,"parent":3,"district":"Timberline Commons","name":"The Avalanche","slug":"the-avalanche","description":"A beloved, loud, slightly battered dive bar with cheap drinks, pool tables, stickers, a small dance floor, and more honest social sorting than the polished village offers.","category":"dive bar","type":"venue","activities":["drinks","pool","dancing","late-night gossip"],"hours":{"open":"16:00","close":"02:00"},"backstory":"The name predates modern sensitivity about mountain risk and survives because locals refuse to let branding consultants near it.","socialTexture":"Quiet at opening, rowdy after ten, and unexpectedly caring when someone needs a safe ride home.","visualAnchors":["stickered bar","pool tables","small dance floor","neon beer glow without logos","snowy windows"]}),
  location({"index":22,"parent":3,"district":"Timberline Commons","name":"Switchyard Pizza","slug":"switchyard-pizza","description":"A fast, crowded pizza counter in a former freight building, serving affordable slices, staff meals, and the food most likely to appear after a difficult shift.","category":"pizza shop","type":"venue","activities":["pizza","staff meals","late food","casual dates"],"hours":{"open":"11:00","close":"01:00"},"backstory":"The ovens sit where railway cargo once waited. A wall of handwritten tabs records community meals paid forward after injuries or bad weeks.","socialTexture":"Families at lunch, workers at dinner, and the entire younger town after midnight.","visualAnchors":["open ovens","freight beams","shared tables","slice counter","handwritten meal tabs"]}),
  location({"index":23,"parent":3,"district":"Timberline Commons","name":"Driftline Laundry","slug":"driftline-laundry","description":"A twenty-four-hour laundromat with oversized machines, vending coffee, folding tables, fogged windows, and surprising emotional importance to seasonal life.","category":"laundromat","type":"venue","activities":["laundry","late-night waiting","people watching","quiet conversation"],"hours":{"open":"00:00","close":"24:00"},"backstory":"Driftline remained when nearly every neighboring service business became visitor-facing. Its owner treats the bulletin board as a public utility.","socialTexture":"Most intimate after midnight, when uniforms turn in circles and nobody has enough energy left to posture.","visualAnchors":["rows of machines","fogged windows","plastic chairs","community bulletin board","snow outside"]}),
  location({"index":24,"parent":3,"district":"Timberline Commons","name":"Highline Climbing Gym","slug":"highline-climbing-gym","description":"A converted warehouse climbing gym with tall walls, training boards, yoga space, and a community that shifts from ski legs to rock season every spring.","category":"climbing gym","type":"venue","activities":["climbing","training","classes","community nights"],"hours":{"open":"06:00","close":"22:00"},"backstory":"Highline was created by guides and patrollers who needed somewhere to train during storm holds and mud season.","socialTexture":"Focused before work, social after work, and especially revealing when somebody must trust a belay partner.","visualAnchors":["tall climbing walls","training boards","chalk haze","warehouse beams","snowy loading door"]}),
  location({"index":25,"parent":3,"district":"Timberline Commons","name":"Edge & Wax","slug":"edge-and-wax","description":"A meticulous ski and snowboard tuning workshop where machines hum late, tools are shared carefully, and equipment failures become personal investigations.","category":"tuning workshop","type":"venue","activities":["ski tuning","board repair","equipment advice","technical conversation"],"hours":{"open":"07:00","close":"22:00"},"backstory":"The shop's founders were racers who cared more about repair culture than retail. Staff still keep a shelf of old bindings that failed in instructive ways.","socialTexture":"Technical and brisk by day, companionable after close when the benches become a place to talk.","visualAnchors":["tuning benches","wax irons","edge machines","organized tools","boards overhead"]}),
  location({"index":26,"parent":3,"district":"Timberline Commons","name":"Juniper House","slug":"juniper-house","description":"NorthVale's largest seasonal-worker residence, with small rooms, shared kitchens, a public-facing common room, courtyard fire barrel, and a lease nobody takes for granted.","category":"employee residence","type":"residence","activities":["shared meals","resident events","courtyard gatherings","housing meetings"],"hours":{"open":"07:00","close":"01:00"},"backstory":"Juniper House was converted from railway housing under the 1978 Vale Accord. Its potential sale has made an ordinary building the emotional center of the current season.","socialTexture":"Private rooms stay invitation-gated; the common room and courtyard are loud, communal, and constantly renegotiated.","visualAnchors":["weathered apartment block","shared kitchen","bulletin board","courtyard fire barrel","gear-lined hallway"]}),
  location({"index":27,"parent":3,"district":"Timberline Commons","name":"The Drift","slug":"the-drift","description":"A compact live-music venue and bar inside a converted loading depot, known for local bands, touring acts, open mics, and friendships formed during soundcheck.","category":"music venue","type":"venue","activities":["live music","open mic","dancing","rehearsals"],"hours":{"open":"18:00","close":"02:00"},"backstory":"The Drift began as an illegal rehearsal room and became licensed only after the town realized closing it would move the same crowd somewhere less safe.","socialTexture":"Staff and musicians own the early evening; the public crowd arrives late; cleanup is often more honest than the show.","visualAnchors":["low stage","loading-depot beams","warm stage lights","standing crowd","back hallway"]}),
  location({"index":28,"parent":4,"district":"NorthVale Mountain","name":"Sunrise Gondola","slug":"sunrise-gondola","description":"The primary enclosed lift from Summit Village to the upper mountain, carrying guests, instructors, patrollers, supplies, and private conversations above the trees.","category":"gondola","type":"transit","activities":["mountain transit","scenic rides","first chair","staff transport"],"hours":{"open":"07:30","close":"16:30"},"backstory":"Installed in 1988, Sunrise is nearing replacement age. Its maintenance history is central to both practical operations and the current expansion debate.","socialTexture":"Crowded and anticipatory at opening; strangely private when two people share a cabin between rushes.","visualAnchors":["dark gondola cabins","snowy terminal","cables over pine forest","operations platform","mountain horizon"]}),
  location({"index":29,"parent":4,"district":"NorthVale Mountain","name":"Midstation Lodge","slug":"midstation-lodge","description":"A practical warming lodge with cafeteria food, large windows, patrol radio traffic, drying racks, and a terrace above the tree line.","category":"mountain lodge","type":"venue","activities":["warming up","lunch","meeting friends","weather watching"],"hours":{"open":"09:00","close":"16:00"},"backstory":"Midstation was rebuilt after a 1974 fire and intentionally kept functional rather than luxurious.","socialTexture":"Family-heavy at lunch, worker-heavy before and after public hours, and calm when weather empties the terrace.","visualAnchors":["cafeteria trays","large mountain windows","drying racks","radio corner","snow terrace"]}),
  location({"index":30,"parent":4,"district":"NorthVale Mountain","name":"NorthVale Ski School","slug":"northvale-ski-school","description":"The resort's lesson center and learning meadow, where instructors manage fear, ambition, children, adults, language differences, and mountain etiquette.","category":"ski school","type":"venue","activities":["ski lessons","snowboard lessons","adaptive instruction","instructor briefings"],"hours":{"open":"08:00","close":"16:00"},"backstory":"The school grew from volunteer weekend lessons and still debates whether teaching should prioritize progression, safety, hospitality, or local culture.","socialTexture":"Chaotic during line-up, focused on snow, and socially active after instructors return their groups.","visualAnchors":["lesson flags","learning meadow","instructor room","equipment racks","gondola backdrop"]}),
  location({"index":31,"parent":4,"district":"NorthVale Mountain","name":"Ski Patrol Headquarters","slug":"ski-patrol-headquarters","description":"A functional patrol base with radios, medical equipment, rescue sleds, maps, drying gear, and a small public first-aid entrance.","category":"patrol station","type":"venue","activities":["first aid","rescue coordination","patrol briefing","mountain safety"],"hours":{"open":"07:00","close":"18:00"},"backstory":"Patrol culture descends directly from White Sunday rescue traditions, though modern professionalism has replaced much of the old mythology.","socialTexture":"Briefings are concise, rescues intense, and end-of-day sweep creates a particular exhausted closeness.","visualAnchors":["rescue sleds","radio wall","medical bay","wet patrol jackets","incident map"]}),
  location({"index":32,"parent":4,"district":"NorthVale Mountain","name":"Avalanche Forecast Center","slug":"avalanche-forecast-center","description":"A compact operations building where forecasters study snow pits, weather stations, wind loading, and human reports before publishing daily conditions.","category":"forecast center","type":"venue","activities":["snow analysis","weather briefing","forecasting","research"],"hours":{"open":"05:30","close":"17:00"},"backstory":"The Center was created after the Vale Accord linked resort expansion to public safety data. It remains technically independent enough to make everyone uncomfortable at useful moments.","socialTexture":"Quiet, analytical, and most intense before dawn or when conditions change faster than models predicted.","visualAnchors":["snowpack boards","weather monitors","field notebooks","radios","dawn through small windows"]}),
  location({"index":33,"parent":4,"district":"NorthVale Mountain","name":"North Bowl","slug":"north-bowl","description":"A wide expert-facing bowl beneath Vale Peak, famous for wind-loaded powder, big views, strict control work, and the fastest way for confidence to become consequence.","category":"ski terrain","type":"outdoor","activities":["expert skiing","powder runs","patrol control","viewing"],"hours":{"open":"08:30","close":"15:30"},"backstory":"North Bowl made the resort nationally known in the 1980s. Its reputation often obscures the daily labor required to open it safely.","socialTexture":"Electric after a storm, sparse in flat light, and entirely subordinate to patrol closure.","visualAnchors":["wide alpine bowl","control signs","wind plume","steep snow face","distant town"]}),
  location({"index":34,"parent":4,"district":"NorthVale Mountain","name":"Juniper Glades","slug":"juniper-glades","description":"Tree-lined intermediate terrain known for filtered light, soft snow, hidden resting spots, and the feeling of briefly leaving the resort behind.","category":"ski terrain","type":"outdoor","activities":["glade skiing","lessons","quiet runs","forest rest"],"hours":{"open":"08:30","close":"15:30"},"backstory":"The glades were selectively thinned by hand rather than clear-cut, creating a local stewardship program that continues each summer.","socialTexture":"Social during lessons, peaceful between crowds, and disorienting in heavy snow.","visualAnchors":["spaced pine trees","soft powder","filtered sunlight","trail markers","quiet forest"]}),
  location({"index":35,"parent":4,"district":"NorthVale Mountain","name":"Halo Terrain Park","slug":"halo-terrain-park","description":"A professionally shaped terrain park with rails, jumps, progression features, a sound system, and a culture equal parts supportive, competitive, and performative.","category":"terrain park","type":"outdoor","activities":["freestyle skiing","snowboarding","training","competitions"],"hours":{"open":"09:00","close":"16:00"},"backstory":"The park was built after local riders stopped waiting for the resort to understand them. Its name comes from the sun ring often visible above the ridge in blowing snow.","socialTexture":"Focused during training, social at feature queues, and vulnerable whenever somebody returns after injury.","visualAnchors":["sculpted jumps","rails","park crew tools","feature queue","high ridge halo"]}),
  location({"index":36,"parent":4,"district":"NorthVale Mountain","name":"Gate Seven","slug":"gate-seven","description":"A controlled backcountry access gate with beacon-check signage, condition boards, a narrow traverse, and the clear boundary between resort services and personal responsibility.","category":"backcountry gate","type":"landmark","activities":["backcountry access","beacon checks","route planning","conditions review"],"hours":null,"backstory":"Gate Seven was formalized after repeated rescues on an informal route into Silver Basin. It is a threshold, not an invitation.","socialTexture":"Serious, quiet, and revealing: experienced people slow down here rather than perform confidence.","visualAnchors":["metal access gate","condition board","beacon checker","wind-scoured ridge","basin beyond"]}),
  location({"index":37,"parent":4,"district":"NorthVale Mountain","name":"Firefly Summit House","slug":"firefly-summit-house","description":"A summit restaurant and overlook with broad windows, a sheltered deck, simple food, and warm light visible from town after evening events.","category":"summit restaurant","type":"venue","activities":["summit dining","scenic views","warming up","sunset events"],"hours":{"open":"09:00","close":"16:30"},"backstory":"The first summit hut used kerosene lamps that looked like fireflies from the valley. The modern building keeps the name without pretending to be rustic.","socialTexture":"Busy at lunch, romantic near last chair, and operationally quiet when weather closes the deck.","visualAnchors":["panoramic windows","sheltered deck","simple timber interior","summit snow","town lights below"]}),
  location({"index":38,"parent":5,"district":"Pine Lake","name":"Pine Lake Nordic Center","slug":"pine-lake-nordic-center","description":"A community-oriented Nordic center with groomed loops, a wax room, rentals, a modest lodge, and athletes ranging from beginners to serious racers.","category":"Nordic center","type":"venue","activities":["cross-country skiing","lessons","training","trail events"],"hours":{"open":"07:00","close":"18:00"},"backstory":"The center began when residents groomed mill roads by snowmobile. It remains more community-driven than the alpine resort.","socialTexture":"Quiet and focused early, social after school, and intensely local during weekend races.","visualAnchors":["groomed tracks","modest lodge","wax room","pine lake edge","morning frost"]}),
  location({"index":39,"parent":5,"district":"Pine Lake","name":"Stillwater Sauna House","slug":"stillwater-sauna-house","description":"A lakeside sauna and bathhouse with cedar rooms, cold-air decks, private treatment spaces, and a communal lounge built around recovery rather than display.","category":"sauna house","type":"venue","activities":["sauna","recovery","cold-air deck","quiet socializing"],"hours":{"open":"09:00","close":"22:00"},"backstory":"Stillwater adapted a former mill bathhouse and became a town ritual only after introducing clear privacy rules and affordable local hours.","socialTexture":"Quiet mornings, sociable evenings, and especially intimate after long mountain days without becoming automatically sexual.","visualAnchors":["cedar sauna","steam","snowy deck","warm lounge","lake view"]}),
  location({"index":40,"parent":5,"district":"Pine Lake","name":"Pine Lake Cabins","slug":"pine-lake-cabins","description":"A small cluster of weathered but comfortable rental cabins among the trees, used by visitors, returning seasonal workers, and locals needing temporary space.","category":"cabins","type":"venue","activities":["cabin stays","fireside meals","quiet weekends","lake walks"],"hours":{"open":"00:00","close":"24:00"},"backstory":"Several cabins began as mill-worker homes. Cabin Nine has been closed pending structural review, which has not stopped people from caring about what it contains.","socialTexture":"Private stays are invitation-gated; paths, porch lights, and the shared fire circle create gentle overlap.","visualAnchors":["small timber cabins","snowy footpaths","porch lights","shared fire circle","pine forest"]}),
  location({"index":41,"parent":5,"district":"Pine Lake","name":"Frostline Boathouse","slug":"frostline-boathouse","description":"A year-round lake outfitter that rents skates and ice gear in winter, boats in summer, and maintains the safety board residents actually trust.","category":"boathouse","type":"venue","activities":["skate rentals","ice safety","summer paddling","lake equipment"],"hours":{"open":"08:00","close":"19:00"},"backstory":"The boathouse survived multiple floods and one failed attempt to turn the lake into a private club.","socialTexture":"Practical in the morning, family-heavy midday, and calm near dusk when staff check the last people off the ice.","visualAnchors":["weathered boathouse","skate racks","ice-thickness board","dock under snow","life-safety gear"]}),
  location({"index":42,"parent":5,"district":"Pine Lake","name":"Elk Meadow Stables","slug":"elk-meadow-stables","description":"A small equestrian center serving local riders, trail horses, therapeutic programs, and working animals without resort-pageantry aesthetics.","category":"stables","type":"venue","activities":["horseback riding","veterinary care","trail lessons","animal-assisted therapy"],"hours":{"open":"07:00","close":"18:00"},"backstory":"The stables occupy former hay meadows protected from development through the Vale Accord land trust.","socialTexture":"Early work is quiet and physical; afternoon lessons are social; animals make dishonesty difficult to sustain.","visualAnchors":["timber barns","snowy paddocks","working tack room","hay steam","mountain horses"]}),
  location({"index":43,"parent":5,"district":"Pine Lake","name":"Bluebird Trailhead","slug":"bluebird-trailhead","description":"A four-season trailhead connecting lake loops, forest paths, summer bike routes, and the lower approach toward Silver Basin.","category":"trailhead","type":"outdoor","activities":["hiking","snowshoeing","trail running","mountain biking"],"hours":null,"backstory":"The name refers to clear cold weather, not easy conditions. The trailhead is often the last reliable cell signal before the basin.","socialTexture":"Busy on bluebird weekends, nearly private in light snow, and always shaped by conditions.","visualAnchors":["trail map","snowshoe tracks","aspen and pine","simple shelter","basin ridge"]}),
  location({"index":44,"parent":5,"district":"Pine Lake","name":"Lakehouse Cafe","slug":"lakehouse-cafe","description":"A bright lakeside cafe serving breakfast, soup, pastries, and simple dinners to Nordic skiers, families, cabin guests, and people extending a quiet conversation.","category":"cafe","type":"venue","activities":["breakfast","pastries","soup","lakeside conversation"],"hours":{"open":"07:00","close":"20:00"},"backstory":"The cafe was once the mill supervisor's house and later a community kitchen during a winter road closure.","socialTexture":"Early athletes, midday families, and a gentle evening crowd that prefers the lake to nightlife.","visualAnchors":["large lake windows","pastry counter","wood stove","Nordic skis outside","soft daylight"]}),
  location({"index":45,"parent":6,"district":"Silver Basin","name":"Silver Basin Hot Springs","slug":"silver-basin-hot-springs","description":"A remote series of developed mineral pools and simple changing rooms set beneath steep snowy walls, reached by controlled road or guide transport in winter.","category":"hot springs","type":"venue","activities":["hot-spring bathing","recovery","quiet dates","weather watching"],"hours":{"open":"09:00","close":"22:00"},"backstory":"Miners used the springs long before formal development. Modern management limits capacity to protect water quality and preserve the place from becoming a spectacle.","socialTexture":"Social in the early evening, quiet in snowfall, and carefully governed by privacy and safety etiquette.","visualAnchors":["mineral pools","snow-covered rock","steam","simple changing lodge","dark basin walls"]}),
  location({"index":46,"parent":6,"district":"Silver Basin","name":"Argent Mine Heritage Site","slug":"argent-mine","description":"Stabilized remnants of the original silver mine, including a safe exhibit tunnel, machinery shed, memorial wall, and restricted deeper workings.","category":"mine heritage site","type":"landmark","activities":["history tours","archive research","memorial visits","photography"],"hours":{"open":"10:00","close":"16:00"},"backstory":"The Argent claims created North Vale and helped destroy its first economy. The site now teaches labor, migration, extraction, and avalanche history without celebrating the boom uncritically.","socialTexture":"Quiet, reflective, and most revealing when personal family stories complicate public history.","visualAnchors":["weathered headframe","stabilized tunnel","memorial wall","old machinery","snow-filled mine road"]}),
  location({"index":47,"parent":6,"district":"Silver Basin","name":"High Country Guides","slug":"high-country-guides","description":"A backcountry guide office and classroom with route maps, avalanche gear, climbing equipment, weather boards, and no patience for performative risk.","category":"guide outfitter","type":"venue","activities":["guided tours","avalanche education","route planning","equipment checks"],"hours":{"open":"06:00","close":"20:00"},"backstory":"The cooperative formed after independent guides pooled insurance, rescue standards, and training resources.","socialTexture":"Brisk before departures, instructional in the afternoon, and socially relaxed only after every group checks back in.","visualAnchors":["route maps","beacon shelves","climbing gear","weather board","shared planning table"]}),
  location({"index":48,"parent":6,"district":"Silver Basin","name":"Basin Rescue Station","slug":"basin-rescue-station","description":"A remote rescue and emergency logistics station with radios, medical supplies, snowmobiles, bunks, and a helipad used only when weather permits.","category":"rescue station","type":"venue","activities":["rescue coordination","medical response","training","weather shelter"],"hours":{"open":"00:00","close":"24:00"},"backstory":"The station grew from a volunteer cache after a 1968 avalanche and now coordinates public agencies, guides, and resort teams without erasing their different responsibilities.","socialTexture":"Quiet between incidents, intensely procedural during calls, and emotionally honest after everyone is accounted for.","visualAnchors":["radio room","medical gear","snowmobiles","bunk area","storm-lit helipad"]}),
  location({"index":49,"parent":6,"district":"Silver Basin","name":"Snowcat Garage","slug":"snowcat-garage","description":"A heated industrial garage maintaining snowcats, tracked vehicles, road equipment, and the machines that make remote winter access possible.","category":"operations garage","type":"venue","activities":["vehicle maintenance","route preparation","mechanical work","crew briefings"],"hours":{"open":"05:00","close":"23:00"},"backstory":"The garage occupies an old ore-processing shed. Its night crews know the basin's shape through machinery, weather, and vibration rather than scenery.","socialTexture":"Technical and noisy on shift, companionable during maintenance pauses, and closed to casual public wandering.","visualAnchors":["snowcats","industrial lights","tool walls","meltwater floor","large garage doors"]}),
  location({"index":50,"parent":6,"district":"Silver Basin","name":"Crow's Nest Lodge","slug":"crows-nest-lodge","description":"A small backcountry lodge with simple rooms, a serious kitchen, drying room, communal table, and views across Silver Basin rather than luxury amenities.","category":"backcountry lodge","type":"venue","activities":["overnight stays","communal meals","guide briefings","storm shelter"],"hours":{"open":"00:00","close":"24:00"},"backstory":"Originally a mine supervisor's bunkhouse, the lodge became a guide base after residents carried lumber in by snowcat during the 1970s.","socialTexture":"Breakfast is operational, dinner communal, and storms make strangers briefly accountable to one another.","visualAnchors":["communal table","drying room","simple bunks","large basin windows","wood stove"]}),
  location({"index":51,"parent":6,"district":"Silver Basin","name":"The Last Light Roadhouse","slug":"last-light-roadhouse","description":"A rustic basin-edge roadhouse serving hot food, drinks, coffee, and local history to guides, mechanics, hot-spring guests, and anyone waiting out road conditions.","category":"roadhouse","type":"venue","activities":["food","drinks","storm waiting","local history"],"hours":{"open":"12:00","close":"01:00"},"backstory":"The roadhouse stands at the last point where evening sun reaches the valley floor in midwinter. Its walls hold maps and photographs, but the owner resists turning history into mythology.","socialTexture":"Slow afternoons, crew-heavy dinners, and crowded storm holds that collapse social distance quickly.","visualAnchors":["low timber room","map-covered wall","long bar","mudroom","last sunlight on snow"]}),
];
